library IEEE;use IEEE.Std_Logic_1164.all;use IEEE.Std_Logic_arith.all;entity Prob_8_9_Controller_vhdl is	port clr_E, set_E, set_F, clr_A_F, incr_A: out Std_Logic; Start, A2, A3, clock, reset_b: in Std_Logic);end Prob_8_9_Controller_vhdl;architecture Behavioral of Prob_8_9_Controller_vhdl is   constant S_idle: Std_Logic := "001";	-- One-Hot   constant S_1: Std_Logic := "010";   constant S_2: Std_Logic := "100";   signal state, next_state: Std_Logic_Vector (2 downto 0);beginprocess (clock, reset_b) begin	-- state transitions   if reset_b = 0 then state <= S_idle;   elsif clock'event and clock = 1 then state <= next_state;end process;process (state, Start, A2, A3) begin	-- next state and output logic   set_E <= 0;   clr_E <= 0;   set_F <= 0;   clr_A_F <= 0;   incr_A <= 0;    case state is      when S_idle => if Start = '1' then clr_A_F <= '1'; next_state <= S1; end if;      when S_1 => incr_A <= '1'; if not A2 then next_state <= S_1; clr_E <= '1';         else set_E <= '1'; if A3 = '1' then next_state <= S_2 else next_state <= S_1;         end if;         end if;      when S_2 => next_state <= S_idle; set_F <= '1'      when others => next_state <= S_idle;   end case;end processend Behavioral;